import csv
import io
import re


def parse_csv(raw_csv: str):
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    records = []
    for row in reader:
        if row and row[0].startswith("\ufeff"):
            row[0] = row[0].lstrip("\ufeff")
        if any(cell.strip() for cell in row):
            records.append(row)

    if not records:
        return {"columns": [], "rows": []}

    width = 4
    date_pattern = re.compile(r"^\s*\d{1,4}[/-]\d{1,2}[/-]\d{1,4}\s*$")

    header_index = None
    for index, row in enumerate(records):
        if len(row) != width or date_pattern.match(row[0]):
            continue
        if index + 1 < len(records) and date_pattern.match(records[index + 1][0]):
            header_index = index
            break

    if header_index is None:
        header_index = next(
            (i for i, row in enumerate(records) if len(row) == width),
            0,
        )

    columns = [value.strip() for value in records[header_index]]
    if len(columns) < width:
        columns.extend([""] * (width - len(columns)))
    elif len(columns) > width:
        columns = columns[: width - 1] + [",".join(columns[width - 1 :])]

    rows = []
    for record in records[header_index + 1 :]:
        if len(record) < width:
            record = record + [""] * (width - len(record))
        elif len(record) > width:
            record = record[: width - 1] + [",".join(record[width - 1 :])]
        rows.append(record)

    return {"columns": columns, "rows": rows}
